import boto3


def get_vision_client(region):
    return boto3.client("rekognition", region_name=region)


def get_translate_client(region):
    return boto3.client("translate", region_name=region)


def get_s3_client(region):
    return boto3.client("s3", region_name=region)

def normalize_labels(response):
    return [{'name': label['Name'], 'confidence': label['Confidence'] / 100.0} for label in response['Labels']]


def normalize_text(response):
    return [text['DetectedText'] for text in response['TextDetections']]


def normalize_safety_score(response):
    return sum([label['Confidence'] for label in response['ModerationLabels']])

import boto3


def image_summary(payload, config=None):
    config = config or {}
    client = boto3.client("rekognition", region_name=config.get("region"))
    labels_response = client.detect_labels(
        Image={"Bytes": payload["image_bytes"]},
        MaxLabels=int(config.get("max_labels", 10)),
    )
    text_response = client.detect_text(
        Image={"Bytes": payload["image_bytes"]},
    )
    labels = [label['Name'] for label in labels_response['Labels']]
    text = ' '.join([text['DetectedText'] for text in text_response['TextDetections']])
    return {"summary": f"Labels: {', '.join(labels)}. Text: {text}"}

import boto3


def alt_text_translate(payload, config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region"))
    response = client.translate_text(
        Text=payload["text"],
        SourceLanguageCode="en",
        TargetLanguageCode=config.get("target_language", "es"),
    )
    return {"translated_text": response['TranslatedText']}

import boto3


def visual_safety_text(payload, config=None):
    config = config or {}
    client = boto3.client("rekognition", region_name=config.get("region"))
    response = client.detect_moderation_labels(
        Image={"Bytes": payload["image_bytes"]},
    )
    unsafe_text = [label['Name'] for label in response['ModerationLabels'] if label['Name'] in config.get('unsafe_keywords', [])]
    return {"unsafe_text": unsafe_text}

import boto3


def image_asset_archive(payload, config=None):
    config = config or {}
    client = boto3.client("s3", region_name=config.get("region"))
    client.put_object(
        Body=payload["image_bytes"],
        Bucket=config.get("bucket_name"),
        Key=payload["image_name"],
    )
    return {"archive_status": "success"}
